def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    def components(points, diagonal=False):
        remaining = set(points)
        result = []
        steps = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        if diagonal:
            steps += [(1, 1), (1, -1), (-1, 1), (-1, -1)]
        while remaining:
            seed = remaining.pop()
            comp = {seed}
            stack = [seed]
            while stack:
                x, y = stack.pop()
                for dx, dy in steps:
                    q = (x + dx, y + dy)
                    if q in remaining:
                        remaining.remove(q)
                        comp.add(q)
                        stack.append(q)
            result.append(comp)
        return result

    def hole_count(cells):
        r0, r1 = min(x for x, y in cells), max(x for x, y in cells)
        c0, c1 = min(y for x, y in cells), max(y for x, y in cells)
        outside = set()
        stack = []
        for x in range(r0, r1 + 1):
            for y in (c0, c1):
                if (x, y) not in cells:
                    stack.append((x, y))
        for y in range(c0, c1 + 1):
            for x in (r0, r1):
                if (x, y) not in cells:
                    stack.append((x, y))
        while stack:
            x, y = stack.pop()
            if (x, y) in outside:
                continue
            outside.add((x, y))
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if dx == dy == 0:
                        continue
                    q = (x + dx, y + dy)
                    if r0 <= q[0] <= r1 and c0 <= q[1] <= c1 and q not in cells and q not in outside:
                        stack.append(q)
        return len(components({(x, y) for x in range(r0, r1 + 1) for y in range(c0, c1 + 1)
                               if (x, y) not in cells and (x, y) not in outside}))

    ordered = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 1, 5) and v not in ordered:
                ordered.append(v)
    classes = []
    for color in ordered:
        cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        classes.append((hole_count(cells), color))
    for comp in components({(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5}):
        holes = hole_count(comp)
        eligible = [(n, color) for n, color in classes if n <= holes]
        color = max(eligible)[1] if eligible else classes[0][1]
        for x, y in comp:
            g[x][y] = color
    return g
